// Shared with the installed-rustc oracle; only supported Rust syntax goes here.
export const destructuringCases = [
  ['tuple swap captures both old values', 'fn main(){let mut a=1;let mut b=2;(a,b)=(b,a);println!("{} {}",a,b);}', '2 1\n'],
  ['nested tuple and array destinations', 'fn main(){let mut a=0;let mut b=0;let mut c=0;(a,[b,c])=(7,[8,9]);println!("{} {} {}",a,b,c);}', '7 8 9\n'],
  ['writes to repeated destinations happen in order', 'fn main(){let mut a=0;(a,a,a)=(1,2,3);println!("{}",a);}', '3\n'],
  ['index expressions observe earlier assignments', 'fn main(){let mut i=0usize;let mut a=[0,0];(i,a[i])=(1,9);println!("{} {:?}",i,a);}', '1 [0, 9]\n'],
  ['RHS and destination side effects each run once in Rust order', 'fn rhs()->(i32,i32){print!("r");(7,8)}fn index(n:usize)->usize{print!("{}",n);n}fn main(){let mut a=[0,0];(a[index(0)],a[index(1)])=rhs();println!(" {:?}",a);}', 'r01 [7, 8]\n'],
  ['array assignees evaluate destinations in order', 'fn index(n:usize)->usize{print!("{}",n);n}fn main(){let mut a=[0,0];[a[index(1)],a[index(0)]]=[7,8];println!(" {:?}",a);}', '10 [8, 7]\n'],
  ['Copy aggregate projection is snapshotted before mutation', 'fn main(){let mut a=[[1,2],[3,4]];[a[1],a[0]]=a;println!("{:?} {:?}",a[0],a[1]);}', '[3, 4] [1, 2]\n'],
  ['tuple fields preserve nested Copy snapshots', 'fn main(){let mut a=([1,2],[3,4]);(a.1,a.0)=a;println!("{:?} {:?}",a.0,a.1);}', '[3, 4] [1, 2]\n'],
  ['tuple rest carries heterogeneous context to suffixes', 'fn main(){let mut a=0u8;let mut b=0u64;(a,..,b)=(7,true,9);println!("{} {}",a,b);}', '7 9\n'],
  ['tuple rest of zero length', 'fn main(){let mut a=0;let mut b=0;(a,..,b)=(7,8);println!("{} {}",a,b);}', '7 8\n'],
  ['array rest carries numeric context', 'fn main(){let mut a=0u8;let mut b=0u8;[a,..,b]=[5,6,7];println!("{} {}",a,b);}', '5 7\n'],
  ['array rest at both sequence edges', 'fn main(){let mut a=0;let mut b=0;[..,a]=[1,2,3];[b,..]=[4,5,6];println!("{} {}",a,b);}', '3 4\n'],
  ['rest-only and unit assignees still evaluate RHS effects', 'fn pair()->(i32,bool){print!("p");(1,true)}fn array()->[i32;2]{print!("a");[1,2]}fn unit(){print!("u")}fn main(){(..)=pair();[..]=array();()=unit();}', 'pau'],
  ['underscore discard does not move an existing String', 'fn main(){let s=String::from("keep");_=s;println!("{}",s);}', 'keep\n'],
  ['ignored non-Copy field and Copy selected field preserve the source', 'struct S{text:String,n:i32}fn main(){let s=S{text:String::from("keep"),n:7};let mut n=0;S{text:_,n}=s;println!("{} {}",s.text,n);}', 'keep 7\n'],
  ['discard inside an aggregate still executes its constructor', 'fn side()->i32{print!("s");3}fn main(){(_,_)=(side(),side());}', 'ss'],
  ['record shorthand, explicit fields and omitted fields', 'struct P{x:i32,y:i32,z:bool}fn main(){let mut x=0;let mut n=0;P{x,y:n,..}=P{x:3,y:7,z:true};println!("{} {}",x,n);}', '3 7\n'],
  ['record field stores follow assignee order rather than declaration order', 'struct P{x:i32,y:i32}fn index(n:usize)->usize{print!("{}",n);n}fn main(){let mut a=[0,0];P{y:a[index(0)],x:a[index(1)]}=P{x:3,y:7};println!(" {:?}",a);}', '01 [7, 3]\n'],
  ['nested record with array destinations', 'struct P{values:[i32;3],valid:bool}fn main(){let mut a=0;let mut b=0;let mut ok=false;P{values:[a,..,b],valid:ok}=P{values:[2,4,6],valid:true};println!("{} {} {}",a,b,ok);}', '2 6 true\n'],
  ['generic records derive constraints from existing destinations', 'struct P<T>{x:T,y:T}fn main(){let mut a=0u16;let mut b=0u16;P{x:a,y:b}=P{x:10,y:20};println!("{} {}",a,b);}', '10 20\n'],
  ['type-alias record assignee resolves declaration namespace', 'mod m{pub struct P<T>{pub x:T,pub y:T}pub type A=P<u8>;}fn main(){let mut a=0u8;m::A{x:a,..}=m::P{x:3u8,y:5u8};println!("{}",a);}', '3\n'],
  ['mutable references are valid scalar destinations', 'fn fill(p:&mut i32,q:&mut i32){(*p,*q)=(3,4);}fn main(){let mut a=0;let mut b=0;fill(&mut a,&mut b);println!("{} {}",a,b);}', '3 4\n'],
  ['implicit dereference record field destinations', 'struct P{x:i32,y:i32}fn fill(p:&mut P){(p.x,p.y)=(5,8);}fn main(){let mut p=P{x:0,y:0};fill(&mut p);println!("{} {}",p.x,p.y);}', '5 8\n'],
  ['owned String swap reinitializes moved local destinations', 'fn main(){let mut a=String::from("a");let mut b=String::from("b");(a,b)=(b,a);println!("{} {}",a,b);}', 'b a\n'],
  ['non-Copy projection transfers ownership', 'fn main(){let pair=(String::from("x"),String::from("y"));let mut a=String::from("");let mut b=String::from("");(a,b)=pair;println!("{} {}",a,b);}', 'x y\n'],
  ['scalar assignment can contain destructuring unit value', 'fn main(){let mut a=0;let mut b=0;let mut u=();u=((a,b)=(2,3));println!("{} {} {:?}",a,b,u);}', '2 3 ()\n'],
  ['right associative nested destructuring', 'fn main(){let mut a=0;let mut b=0;let mut u=();(u,)=(((a,b)=(4,5)),);println!("{} {} {:?}",a,b,u);}', '4 5 ()\n'],
  ['const fn uses the same typed assignee lowering', 'const fn f(mut a:u32,mut b:u32)->u32{(a,b)=(b,a);a*10+b}const N:u32=f(2,7);fn main(){println!("{} {}",N,f(3,8));}', '72 83\n'],
  ['const record and array assignments', 'struct P{x:u32,y:u32}const N:u32={let mut a=0u32;let mut b=0u32;P{x:a,y:b}=P{x:3,y:4};[a,b]=[b,a];a*10+b};fn main(){println!("{}",N);}', '43\n'],
  ['mutable closure captures tuple destinations', 'fn main(){let mut a=0;let mut b=0;let mut f=||{(a,b)=(3,4);};f();println!("{} {}",a,b);}', '3 4\n'],
  ['mutable closure captures record destinations', 'struct P{x:i32,y:i32}fn main(){let mut a=0;let mut b=0;let mut f=||{P{x:a,y:b}=P{x:3,y:4};};f();println!("{} {}",a,b);}', '3 4\n'],
  ['discarded capture remains callable more than once', 'fn main(){let s=String::from("s");let f=||{_=s;};f();f();println!("{}",s);}', 's\n'],
  ['divergent RHS suppresses all destination effects', 'fn index()->usize{print!("bad");0}fn f()->i32{let mut a=[0];(a[index()],)=(return 9,);0}fn main(){println!("{}",f());}', '9\n'],
  ['contextual floats in tuple assignees stay f32', 'fn main(){let mut a=0f32;let mut b=0f32;(a,b)=(1.25,2.5);println!("{} {}",a,b);}', '1.25 2.5\n'],
  ['contextual tuple elements of array assignees', 'fn main(){let mut a=0u8;let mut b=false;let mut c=0u8;let mut d=false;[(a,b),(c,d)]=[(1,true),(2,false)];println!("{} {} {} {}",a,b,c,d);}', '1 true 2 false\n'],
  ['single tuple and trailing separators', 'fn main(){let mut a=0;(a,)=(7,);[a,]=[9,];println!("{}",a);}', '9\n'],
];
export const destructuringCompileFailCases = [
  ['immutable tuple destination', 'fn main(){let a=0;(a,)=(1,);}'],
  ['tuple assignee arity mismatch', 'fn main(){let mut a=0;(a,)=(1,2);}'],
  ['array assignee arity mismatch', 'fn main(){let mut a=0;[a]=[1,2];}'],
  ['rest minimum arity mismatch', 'fn main(){let mut a=0;let mut b=0;[a,..,b]=[1];}'],
  ['two tuple rest positions', 'fn main(){(..,..)=(1,2);}'],
  ['two array rest positions', 'fn main(){[..,..]=[1,2];}'],
  ['literal is not a destructuring place', 'fn main(){(1,)=(2,);}'],
  ['call is not a destructuring place', 'fn f()->i32{0}fn main(){(f(),)=(2,);}'],
  ['standalone rest is not an assignee', 'fn main(){..=1;}'],
  ['rest is not a value expression', 'fn main(){let a=(..); }'],
  ['record rest is not a value expression', 'struct S{x:i32}fn main(){let s=S{..};}'],
  ['placeholder is not a value expression', 'fn main(){let a=_;}'],
  ['unknown record assignee field', 'struct P{x:i32}fn main(){let mut a=0;P{y:a}=P{x:1};}'],
  ['duplicate record assignee field', 'struct P{x:i32}fn main(){let mut a=0;P{x:a,x:a}=P{x:1};}'],
  ['missing record assignee field requires rest', 'struct P{x:i32,y:i32}fn main(){let mut a=0;P{x:a}=P{x:1,y:2};}'],
  ['nominal record types cannot be interchanged', 'struct P{x:i32}struct Q{x:i32}fn main(){let mut a=0;P{x:a}=Q{x:1};}'],
  ['tuple assignee does not match an array', 'fn main(){let mut a=0;(a,)=[1];}'],
  ['array assignee does not match a tuple', 'fn main(){let mut a=0;[a]=(1,);}'],
  ['destructuring compound assignment is forbidden', 'fn main(){let mut a=0;(a,)+=(1,);}'],
  ['shared reference is not a writable destination', 'fn f(p:&i32){(*p,)=(3,);}fn main(){}'],
  ['destructuring still rejects a borrowed destination', 'fn main(){let mut a=0;let r=&a;(a,)=(1,);println!("{}",r);}'],
  ['non-Copy source cannot be reused after moving both fields', 'fn main(){let pair=(String::from("x"),String::from("y"));let mut a=String::from("");let mut b=String::from("");(a,b)=pair;println!("{:?}",pair);}'],
  ['moved record cannot be reinitialized through a field', 'struct P{x:String}fn take(p:P){}fn main(){let mut p=P{x:String::from("a")};take(p);(p.x,)=(String::from("b"),);}'],
  ['moved value in an index is checked after previous writes', 'fn ix(s:String)->usize{0}fn main(){let s=String::from("x");let t=s;let mut a=[0];(a[ix(s)],)=(1,);}'],
  ['incompatible numeric destination types', 'fn main(){let mut a=0u8;let mut b=0u16;[a,b]=[1,2];}'],
  ['immutable binding cannot call a mutation closure', 'fn main(){let mut a=0;let f=||{(a,)=(2,);};f();}'],
];
